    return a.etiqueta == b.etiqueta && a.cantidad == b.cantidad;
}
bool operator==(const Medida& a, const Medida& b) { return mismo_valor(a, b); }
bool operator!=(const Medida& a, const Medida& b) { return !(a == b); }

int main() {
    const Medida buscada{"A", 2};
    const std::vector<Medida> pares{{"A", 2}, {"A", 3}, {"B", 2}};
    for (const auto& otra : pares) {
        std::cout << (buscada == otra) << ":" << (buscada != otra) << "\n";
    }
    const std::vector<Medida> medidas{{"A", 2}, {"A", 3}, {"A", 2}, {"B", 2}};
    std::size_t cantidad = 0;
    for (const auto& medida : medidas) {
        if (medida == buscada) { ++cantidad; }
    }
    std::cout << "Coincidencias:" << cantidad;
    return 0;
}
